    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified&&r.withinShape,r.reason);return r;}
    static Result close(Snapshot x,Snapshot a,Packet p,PrivatePool pool,int depth){Result r=ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(rows(x,a),p,pool,null,16,depth,512,256,WORK);require(r.closed&&r.instantiatedUnits,r.reason);ContextUniversalFrozenConstraints.check(r,depth,()->{});Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:r.proofs)audit(v,seen);return r;}
    static Proof unit(Result r,String name){return r.proofs.stream().filter(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals(name)).findFirst().get();}
    static void audit(Proof p,Set<Proof> seen){if(!seen.add(p))return;require(p.exchanged==null,"no imported owner in flattened audit");if(p.original!=null){require(p.original.parts.contains(p.part)&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"actual whole original Source0");return;}if(p.input!=null){require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual carried Item/Support");return;}Set<Source> sources=new HashSet<>();int depth;Residual expected;
        if(p.producer!=null){audit(p.producer,seen);sources.addAll(p.producer.support.sources);depth=p.producer.support.depth;List<Residual> donors=new ArrayList<>();for(Proof d:p.donors){audit(d,seen);sources.addAll(d.support.sources);depth=Math.max(depth,d.support.depth);donors.add(d.clause);}if(p.groundedMixedRecipe||p.instantiatedUnitRecipe){require(!p.symbolicHeadRecipe&&p.conclusion>=0&&p.instantiatedDonors.size()==p.donors.size(),"distinct actual mixed recipe, complete instance inventory");ContextUniversalInputResiduals.GroundedApplication binding=p.instantiatedUnitRecipe?ContextUniversalInputResiduals.applyInstantiatedUnits(p.producer.clause,p.conclusion,donors,()->{}):ContextUniversalInputResiduals.applyGroundedMixedUnits(p.producer.clause,p.conclusion,donors,()->{});require(binding!=null,"one joint grounded substitution");expected=binding.conclusion;boolean fixed=false,symbolic=false;for(int i=0;i<donors.size();++i){Residual d=donors.get(i),instance=p.instantiatedDonors.get(i);fixed|=d.variables.isEmpty();symbolic|=!d.variables.isEmpty();require(instance.variables.isEmpty()&&instance.equivalent(binding.instances.get(i),()->{})&&ContextUniversalInputResiduals.instance(d,instance,()->{}),"actual parent admits this fixed instance, no instantiation depth charged");}require(symbolic&&(!p.groundedMixedRecipe||fixed&&expected.variables.isEmpty()),"actual symbolic donor, old mixed recipe still requires fixed donor/output");}
            else {require(p.instantiatedDonors.isEmpty(),"old recipe has no invented instances");expected=p.symbolicHeadRecipe?ContextUniversalInputResiduals.applySymbolicHeadFixedUnits(p.producer.clause,p.conclusion,donors,()->{}):p.conclusion<0?ContextUniversalInputResiduals.applyFixedPositiveUnits(p.producer.clause,donors,()->{}):ContextUniversalInputResiduals.applyFixedSignedUnits(p.producer.clause,p.conclusion,donors,()->{});}}
        else {audit(p.unit,seen);audit(p.horn,seen);sources.addAll(p.unit.support.sources);sources.addAll(p.horn.support.sources);depth=Math.max(p.unit.support.depth,p.horn.support.depth);expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});}
        require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"typed inference replay");require(p.support.sources.equals(sources)&&p.support.depth==depth+1,"all complete parent Sources and max-parent+1");
    }
    static void nativeCase(String rule,String first,String second,String name,boolean sign,boolean symbolicHead)throws Exception {
        Snapshot x=bind(true,"!anchor(1);"+first+second),a=bind(false,rule);Packet p=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,p,null,1);Proof out=unit(r,name);require(out.instantiatedUnitRecipe&&!out.groundedMixedRecipe&&!out.symbolicHeadRecipe&&out.support.depth==1&&out.support.sources.size()==3&&out.clause.literals.get(0).positive==sign&&out.clause.variables.isEmpty()!=symbolicHead,"distinct real instantiated-unit recipe1/three Sources");Result old=ContextUniversalFrozenConstraints.closeSignedGroundedMixed(rows(x,a),p,null,null,16,16,512,256,WORK);require(old.closed&&!old.instantiatedUnits&&unit(old,name).support.depth==2,"old mixed entry retains binary2 scope");
        Source rs=ContextPrivateWitnessPoolRunner.source(a,rule),fs=ContextPrivateWitnessPoolRunner.source(x,first),ss=ContextPrivateWitnessPoolRunner.source(x,second);ContextProductionCapture.Snapshot nativeResult=ContextUniversalGroundedSymbolicEvidenceRunner.observe(new String[]{rule,first,second},new Source[]{rs,fs,ss},new int[]{0,1,2});ContextUniversalSymbolicDonorEvidenceRunner.gaps(nativeResult);boolean found=false;
        if(!symbolicHead){for(Application e:nativeResult.applications)if(e.conclusion.predicate.equals(name)&&e.conclusion.positive==sign){require(e.steps==1&&out.clause.equivalent(ContextUniversalInputResiduals.fact(e.conclusion,()->{}),()->{})&&e.premises.size()==out.instantiatedDonors.size(),"actual native ground conclusion/grade/group agree");for(Residual instance:out.instantiatedDonors)require(e.premises.stream().anyMatch(f->instance.equivalent(ContextUniversalInputResiduals.fact(f,()->{}),()->{})),"every stored donor instance in actual native group");require(ContextUniversalInputResiduals.instance(out.producer.clause,ContextUniversalInputResiduals.event(e,()->{}),()->{}),"one actual native full producer binding");found=true;}}
        else {for(ContextProductionCapture.Residual e:nativeResult.residuals)if(e.conclusion.literals.size()==1&&e.conclusion.literals.get(0).predicate.equals(name)&&e.premises.size()==2){require(e.steps==1&&out.clause.equivalent(ContextUniversalInputResiduals.schema(e.conclusion,()->{}),()->{}),"actual complete native universal residual1 agrees");for(Residual instance:out.instantiatedDonors)require(e.premises.stream().anyMatch(f->instance.equivalent(ContextUniversalInputResiduals.fact(f,()->{}),()->{})),"all actual native residual donor instances retained");require(e.producerSupports.stream().anyMatch(s->s.depth==0&&s.sources.equals(out.producer.support.sources)),"same original whole producer Source0");found=true;}}
        require(found,"actual native result observed, not full replay completeness");
        if(!symbolicHead){ConstraintTransfer t=ContextWitnessResultTransport.transferConstraints(r,p,1,WORK);require(t.transferred&&ContextUniversalSignedProductAudit.bind(r,t,65536,WORK).bound,"exact fixed product at fact1");require(t.output.items.stream().anyMatch(i->i.atom.predicate.equals(name)&&i.proofs.contains(out.support)),"fixed output retains complete Source/grade");ConstraintTransfer low=ContextWitnessResultTransport.transferConstraints(r,p,0,WORK);require(!low.transferred&&low.output==null,"bound0 atomic fixed refusal");}
        else {ConstraintTransfer t=ContextWitnessResultTransport.transferConstraints(r,p,0,WORK);require(t.transferred&&ContextUniversalSignedProductAudit.bind(r,t,65536,WORK).bound,"symbolic output withheld, fixed audit alone insufficient");Map<Cut,Result> all=new LinkedHashMap<>();all.put(Cut.of(x),close(x,null,p,null,1));all.put(Cut.of(a),r);ContextUniversalSignedUnitExchange.Collection yes=ContextUniversalSignedUnitExchange.collect(x,p,new ArrayList<>(all.keySet()),all,512,256,1,WORK);require(yes.collected&&yes.output.units.stream().anyMatch(u->u.clause.equivalent(out.clause,()->{})&&u.support.equals(out.support)),"universal result collects at actual1");ContextUniversalSignedUnitExchange.Collection low=ContextUniversalSignedUnitExchange.collect(x,p,new ArrayList<>(all.keySet()),all,512,256,0,WORK);require(!low.collected&&low.output==null,"independent symbolic bound0 refuses");Snapshot opinion=bind(false,"!r(1,987654);");Result consumer=ContextUniversalFrozenConstraints.closeSignedUnits(rows(x,opinion),p,null,yes.output,16,16,512,256,WORK);require(consumer.closed&&consumer.xRefuted&&!consumer.instantiatedUnits&&consumer.emptyProofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"old binary consumer authenticates new owner, unmentioned value empty2/four Sources");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:ContextUniversalFrozenConstraints.rejectionEvidence(consumer,WORK))audit(v,seen);require(seen.stream().anyMatch(v->v.instantiatedUnitRecipe&&v.instantiatedDonors.size()==2),"flattened historical proof keeps actual new recipe/instances without owner");}
    }
    static void scopeAndDepth()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u); !@v q(v);"),a=bind(false,"!@x p(x)&&q(x)->r(x);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Result free=close(x,a,p,null,16);require(unit(free,"r").support.depth==2&&!unit(free,"r").instantiatedUnitRecipe,"free donor arguments stay binary2, no domain enumeration");Snapshot fixedHead=bind(false,"!@x p(x)&&q(x)->r(1);");Result fixed=close(x,fixedHead,p,null,16);require(unit(fixed,"r").support.depth==2&&!unit(fixed,"r").instantiatedUnitRecipe,"fixed conclusion cannot hide free donor arguments");
        Snapshot dx=bind(true,"!anchor(1); !@u p(u,u); !@v q(v,v);"),bad=bind(false,"!@x p(x,1)&&q(x,2)->r(x);");Result incompatible=close(dx,bad,ContextPrivateWitnessPoolRunner.common(dx),null,16);require(incompatible.proofs.stream().noneMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")),"shared binding cannot splice diagonal1/2");
        Snapshot hx=bind(true,"!anchor(1); !@u a(u,u); !@v q(v); !@v s(v);"),history=bind(false,"!@u a(u,u)->p(u,u); !@x p(x,1)&&q(x)&&s(x)->r(x);");Result hr=close(hx,history,ContextPrivateWitnessPoolRunner.common(hx),null,16);Proof h=unit(hr,"r");require(h.instantiatedUnitRecipe&&h.support.depth==2&&h.support.sources.size()==5&&h.donors.stream().anyMatch(d->d.support.depth==1&&!d.clause.variables.isEmpty()),"derived universal parent1 retains true output2/five Sources");
        Snapshot fx=bind(true,"!p(1); !q(1);"),fr=bind(false,"!@x p(x)&&q(x)->r(x);");Result allFixed=close(fx,fr,ContextPrivateWitnessPoolRunner.common(fx),null,1);require(!unit(allFixed,"r").instantiatedUnitRecipe,"all-fixed donors retain separate recipe");Result cap=ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(rows(x,a),p,null,null,1,16,512,256,WORK);require(!cap.closed&&cap.proofs.isEmpty(),"round limit hides prefix");cap=ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(rows(x,a),p,null,null,16,16,512,256,1);require(!cap.closed&&cap.proofs.isEmpty(),"work limit hides prefix");
    }
    static void originsAndAlternatives()throws Exception {
        String generate="!@u @v p(u,1)&&q(u,1)->~r(u,v);",target="!@u @v ~r(u,v)&&s(u,1)&&t(v)->~done(u,v);";Snapshot x=bind(true,"!anchor(1); !t(1); !@u p(u,1); "+generate+target),a=bind(false,"!$u q(u,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Result r=close(x,a,p,pool,16);Proof out=unit(r,"r");require(out.instantiatedUnitRecipe&&out.support.depth==1&&out.support.sources.size()==3&&out.clause.variables.size()==1&&out.clause.origins.size()==1&&out.support.sources.contains(a.primary.get(0).source),"private Origin binding and declared universal head survive new mixed1");
        Snapshot b=bind(false,"!$u s(u,1);");Snapshot split=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);PrivatePool two=ContextWitnessResultTransport.privatePool(p,x,split,WORK);Result distinct=close(x,split,p,two,16);require(distinct.proofs.stream().noneMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("done")),"different actual witness Origins do not unify through a symbolic donor");
        Snapshot bundle=bind(false,"!$u q(u,1)&&s(u,1);");PrivatePool same=ContextWitnessResultTransport.privatePool(p,x,bundle,WORK);Result joined=close(x,bundle,p,same,16);Proof done=unit(joined,"done");require(done.support.depth==2&&done.support.sources.size()==5&&done.clause.origins.size()==1&&done.support.sources.contains(bundle.primary.get(0).source),"same physical binding joins, max-parent2/all five Sources");ConstraintTransfer transferred=ContextWitnessResultTransport.transferConstraintsPrivate(joined,same,2,WORK);require(transferred.transferred&&ContextUniversalSignedProductAudit.bind(joined,transferred,65536,WORK).bound,"known actual private Origin fixed result transported with all parents");
        Snapshot opinion=bind(false,"!@u @v r(u,v);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,opinion),WORK);PrivatePool grouped=ContextWitnessResultTransport.privatePool(p,x,group,WORK);Result no=close(x,group,p,grouped,16);require(no.xRefuted&&no.emptyProofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4&&v.support.sources.contains(a.primary.get(0).source)),"private symbolic1 versus independent universal yields empty2/full binding Source");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:ContextUniversalFrozenConstraints.rejectionEvidence(no,WORK))audit(v,seen);require(seen.stream().anyMatch(v->v.instantiatedUnitRecipe),"rejection retains new private recipe");
        Snapshot ax=bind(true,"!anchor(1); !@u p(u,u); !@v q(v);"),producer=bind(false,"!@x @y p(x,1)&&q(x)->~r(x,y);"),loop=bind(false,"!@u @v r(u,v)->r(u,v);");Snapshot alts=ContextProductionNativeBinding.trusted("own",Arrays.asList(producer,loop),WORK);Packet ap=ContextPrivateWitnessPoolRunner.common(ax);Map<Cut,Result> all=new LinkedHashMap<>();all.put(Cut.of(ax),close(ax,null,ap,null,16));all.put(Cut.of(alts),close(ax,alts,ap,null,16));List<Proof> alternatives=new ArrayList<>();for(Proof v:all.get(Cut.of(alts)).proofs)if(v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r"))alternatives.add(v);require(alternatives.size()==2&&alternatives.stream().anyMatch(v->v.support.depth==1&&v.support.sources.size()==3)&&alternatives.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"Source superset2 kept alongside base1");ContextUniversalSignedUnitExchange.Collection low=ContextUniversalSignedUnitExchange.collect(ax,ap,new ArrayList<>(all.keySet()),all,512,256,1,WORK);require(!low.collected&&low.output==null,"shorter subset cannot hide deeper exact-Source alternative");require(ContextUniversalSignedUnitExchange.collect(ax,ap,new ArrayList<>(all.keySet()),all,512,256,2,WORK).collected,"both exact Source minima collect at2");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("instantiated-unit-applications-").toString());nativeCase("!@x p(x,1)&&q(x)->r(x);","!@u p(u,u);","!@v q(v);","r",true,false);nativeCase("!@x p(x,1)&&q(x)->~r(x);","!@u p(u,u);","!@v q(v);","r",false,false);nativeCase("!@x left(x)&&right(x,1)->p(x);","!@u ~p(u);","!@v right(v,v);","left",false,false);nativeCase("!@x @y p(x)&&q(x)->~r(x,y);","!@u p(u);","!q(1);","r",false,true);nativeCase("!@x @y p(x,1)&&q(x)->~r(x,y);","!@u p(u,u);","!@v q(v);","r",false,true);scopeAndDepth();originsAndAlternatives();System.out.println("CONTEXT_UNIVERSAL_INSTANTIATED_UNIT_APPLICATIONS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
